B.anz=new A.ag("Mesajlar",null,null,null,null,null,null,null,null,null)
B.anA=new A.ag("K",null,B.Nl,null,null,null,null,null,null,null)
B.anB=new A.ag("Devam edeyim",null,null,null,null,null,null,null,null,null)
